// Type-level compatibility of the plugin interface with a baseline (origin/main), for
// `node scripts/plugin-build.mjs --api-types module|web`. The baseline's sources are
// copied into the package (`.api-base/`, git-ignored, at the same depth as `src/`, so
// their relative imports resolve), a generated file assigns the current interface to the
// old one, and the package's own checker (tsc, svelte-check) judges it.
//
// Values plugins call: every new value must fit every old use (one assignment of the
// whole module). Types: draw hands most of them to plugins, so the new type must fit the
// old one; the types plugins hand to draw (PLUGIN_PROVIDES) go the other way.
// Limits: method-style parameters are bivariant in TypeScript, and `any` checks nothing.
import { existsSync, mkdirSync, rmSync, symlinkSync, writeFileSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { execFileSync, spawnSync } from 'node:child_process';

export const PLUGIN_PROVIDES = ['ModulePart', 'ServerPart', 'WebPart'];
const PARTS = {
  module: { dir: 'module', archive: 'module/src', files: { Module: 'src/plugin-api' } },
  web: { dir: 'web', archive: 'web/src/lib', files: { Client: 'src/lib/plugin-api', Server: 'src/lib/server/plugin-api' } },
};

/** The generated assertions; `lines` maps a line number to the name it checks. */
export function compatSource(files, typesOf) {
  const lines = ['// Generated by scripts/plugin-api-types.mjs; do not edit or commit.', 'type Is<T extends true> = T;'];
  const names = {};
  for (const [label, file] of Object.entries(files)) {
    lines.push(`import * as Old${label} from './.api-base/${file.replace(/^src\//, '')}';`, `import * as New${label} from './${file}';`);
  }
  for (const [label, file] of Object.entries(files)) {
    names[lines.length + 1] = `${file}: values`;
    lines.push(`export const values${label}: typeof Old${label} = New${label};`);
    for (const type of typesOf(file)) {
      const [from, to] = PLUGIN_PROVIDES.includes(type) ? ['Old', 'New'] : ['New', 'Old'];
      names[lines.length + 1] = `${file}: '${type}'`;
      lines.push(`export type ${label}_${type} = Is<[${from}${label}.${type}] extends [${to}${label}.${type}] ? true : false>;`);
    }
  }
  return { text: `${lines.join('\n')}\n`, names };
}

/** `exportedTypes` comes from plugin-build.mjs (passed in to keep the two modules acyclic). */
export function apiTypeProblems(root, part, exportedTypes, ref = 'origin/main') {
  const spec = PARTS[part];
  if (!spec) throw new Error(`plugin rule: --api-types takes module or web, not '${part}'`);
  const pkg = join(root, spec.dir), base = join(pkg, '.api-base');
  const git = (...args) => execFileSync('git', args, { cwd: root, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  const commit = git('rev-parse', '--verify', `${ref}^{commit}`).trim();
  const scratch = [base, join(pkg, 'api-compat.generated.ts'), join(pkg, 'tsconfig.api.json')];
  const clean = () => { for (const path of scratch) rmSync(path, { recursive: true, force: true }); };
  clean();
  try { return check(); } finally { if (!process.env.PLUGIN_API_KEEP) clean(); }
  function check() {
  mkdirSync(base, { recursive: true });
  const tar = execFileSync('git', ['archive', commit, spec.archive], { cwd: root, maxBuffer: 1 << 28 });
  execFileSync('tar', ['-x', '-C', base, '--strip-components=2'], { input: tar });
  // Bindings are governed by the wire check; generated classes never match across copies.
  if (part === 'web') symlinkSync('../src/module_bindings', join(base, 'module_bindings'));
  const present = Object.fromEntries(Object.entries(spec.files).filter(([, file]) => existsSync(join(base, `${file.replace(/^src\//, '')}.ts`))));
  if (!Object.keys(present).length) return [];
  const { text, names } = compatSource(present, file => exportedTypes(readFileSync(join(base, `${file.replace(/^src\//, '')}.ts`), 'utf8')));
  writeFileSync(join(pkg, 'api-compat.generated.ts'), text);
  const bin = name => join(pkg, 'node_modules/.bin', name);
  let output;
  if (part === 'module') {
    writeFileSync(join(pkg, 'tsconfig.api.json'), JSON.stringify({ extends: './tsconfig.json', include: [], files: ['api-compat.generated.ts'] }));
    output = spawnSync(bin('tsc'), ['--noEmit', '--pretty', 'false', '-p', 'tsconfig.api.json'], { cwd: pkg, encoding: 'utf8' }).stdout;
  } else {
    spawnSync(bin('svelte-kit'), ['sync'], { cwd: pkg, encoding: 'utf8' });
    const include = ['.svelte-kit/ambient.d.ts', '.svelte-kit/non-ambient.d.ts', 'src/app.d.ts', 'src/auth-provider.d.ts', 'api-compat.generated.ts'].filter(f => existsSync(join(pkg, f)));
    writeFileSync(join(pkg, 'tsconfig.api.json'), JSON.stringify({ extends: './tsconfig.json', include }));
    output = spawnSync(bin('svelte-check'), ['--tsconfig', './tsconfig.api.json', '--output', 'machine'], { cwd: pkg, encoding: 'utf8' }).stdout;
  }
  const problems = [];
  for (const line of output.split('\n')) {
    // tsc: api-compat.generated.ts(12,14): error TS…  svelte-check: <ts> ERROR "api-compat.generated.ts" 12:14 "…"
    const match = /^api-compat\.generated\.ts\((\d+),\d+\): error \w+: (.*)$/.exec(line) ?? /ERROR "api-compat\.generated\.ts" (\d+):\d+ "(.*)"$/.exec(line);
    if (match) problems.push(`plugin rule: ${names[match[1]] ?? `line ${match[1]}`} changed incompatibly; that needs a breaking release (a minor on 0.x, a major from 1.0). ${match[2]}`);
    else if (/^(?:[^(]+\(\d+,\d+\): error |\d+ ERROR )/.test(line)) problems.push(`plugin rule: the interface check could not compile: ${line}`);
  }
  return problems;
  }
}
